declare(strict_types=1); require __DIR__.'/config.php'; if(!isLoggedIn()){header('Location:auth.php');exit;} $id=(int)$_SESSION['user_id'];$error='';$ok='';$u=db()->prepare('SELECT * FROM users WHERE id=?');$u->execute([$id]);$user=$u->fetch();
if($_SERVER['REQUEST_METHOD']==='POST'){try{$name=trim($_POST['username']??'');if(strlen($name)<3)throw new RuntimeException('Ник должен содержать минимум 3 символа.');$avatar=$user['avatar_path'];if(!empty($_FILES['avatar']['tmp_name'])){$f=$_FILES['avatar'];if($f['error']!==UPLOAD_ERR_OK||$f['size']>2*1024*1024)throw new RuntimeException('Выберите изображение до 2 МБ.');$info=@getimagesize($f['tmp_name']);if(!$info||!in_array($info[2],[IMAGETYPE_JPEG,IMAGETYPE_PNG,IMAGETYPE_WEBP],true))throw new RuntimeException('Разрешены JPG, PNG и WEBP.');$dir=__DIR__.'/uploads';if(!is_dir($dir))mkdir($dir,0755,true);$ext=[IMAGETYPE_JPEG=>'jpg',IMAGETYPE_PNG=>'png',IMAGETYPE_WEBP=>'webp'][$info[2]];$avatar='uploads/avatar-'.$id.'-'.time().'.'.$ext;move_uploaded_file($f['tmp_name'],__DIR__.'/'.$avatar);}$fields=[$name,$avatar];$sql='UPDATE users SET username=?,avatar_path=?';if(trim($_POST['new_password']??'')!==''){if(strlen($_POST['new_password'])<8)throw new RuntimeException('Новый пароль — минимум 8 символов.');$sql.=',password_hash=?';$fields[]=password_hash($_POST['new_password'],PASSWORD_DEFAULT);}$sql.=' WHERE id=?';$fields[]=$id;db()->prepare($sql)->execute($fields);$_SESSION['username']=$name;$ok='Профиль сохранён.';$u->execute([$id]);$user=$u->fetch();}catch(Throwable $e){$error=$e->getMessage();}}
?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Профиль — BOMBALA</title><link rel="stylesheet" href="styles.css"></head><body><header class="topbar"><a class="logo" href="index.php"><img src="assets/bombala-logo.png" alt="BOMBALA"></a><div class="head-space"></div><a class="header-link" href="index.php">К плейлистам</a></header><main class="profile-page"><a class="back" href="index.php">← Назад</a><section class="profile-card"><div class="profile-title"><div class="avatar"><?php if($user['avatar_path']):?><img src="<?=e($user['avatar_path'])?>" alt="Аватар"><?php else:?><?=e(strtoupper(substr($user['username'],0,1)))?><?php endif;?></div><div><p class="eyebrow">ЛИЧНЫЙ КАБИНЕТ</p><h1>Настройки профиля</h1></div></div><form method="post" enctype="multipart/form-data"><label>Аватар<span class="upload-control"><input type="file" name="avatar" accept="image/png,image/jpeg,image/webp"><b>Выбрать изображение</b><small>JPG, PNG или WEBP · до 2 МБ</small></span></label><label>Ник<input name="username" value="<?=e($user['username'])?>" required></label><label>Новый пароль <small>оставьте пустым, чтобы не менять</small><input type="password" name="new_password" autocomplete="new-password"></label><?php if($error):?><p class="error"><?=e($error)?></p><?php endif;?><?php if($ok):?><p class="success"><?=e($ok)?></p><?php endif;?><button>Сохранить изменения</button></form></section></main></body></html>
